'use strict';

var words2uint64 = require( '@stdlib/number/uint64/ctor' ).of;
var and = require( './../lib' );

// Define a mask that only keeps the middle 32 bits (bits 16 to 47):
var mask = words2uint64( 0x0000ffff, 0xffff0000 );

var values = [
	words2uint64( 0x12345678, 0x9abcdef0 ),
	words2uint64( 0x11112222, 0x33334444 ),
	words2uint64( 0xaaaabbbb, 0xccccdddd ),
	words2uint64( 0xffffffff, 0xffffffff )
];

var v;
var i;
for ( i = 0; i < values.length; i++ ) {
	v = and( values[ i ], mask );
	console.log( '0x%s & 0x%s = 0x%s', values[ i ].toString( 16 ), mask.toString( 16 ), v.toString( 16 ) );
}
